class _LoginState extends State<Login>{final email=TextEditingController(),pw=TextEditingController();bool busy=false;
Future<void> go() async {if(email.text.trim().isEmpty||pw.text.isEmpty){msg(context,'أدخل البريد وكلمة المرور');return;} setState(()=>busy=true);try{final res=await db.auth.signInWithPassword(email:email.text.trim(),password:pw.text); final uid=res.user?.id;if(uid==null)throw Exception('لم يتم تسجيل الدخول');final row=await db.from('admins').select('user_id').eq('user_id',uid).maybeSingle();if(row==null){await db.auth.signOut();throw Exception('هذا الحساب غير مخوّل للإدارة');}if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Home()));}catch(e){if(mounted)msg(context,e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.shield_outlined,size:65,color:blue),const SizedBox(height:14),const Text('XXX',style:TextStyle(fontSize:32,fontWeight:FontWeight.bold,color:blue)),const Text('مركز إدارة سيد الدكان'),const SizedBox(height:30),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'البريد الإلكتروني')),const SizedBox(height:12),TextField(controller:pw,obscureText:true,decoration:const InputDecoration(labelText:'كلمة المرور')),const SizedBox(height:20),SizedBox(width:double.infinity,height:52,child:ElevatedButton(onPressed:busy?null:go,style:ElevatedButton.styleFrom(backgroundColor:blue),child:Text(busy?'جارٍ التحقق...':'دخول'))),const SizedBox(height:12),const Text('دخول حساب المدير المصرّح به فقط',style:TextStyle(color:Colors.white54))]))))));}
