class ProductForm extends StatefulWidget{final Map<String,dynamic>? product;const ProductForm({super.key,this.product});@override State<ProductForm> createState()=>_ProductFormState();}
class _ProductFormState extends State<ProductForm>{late final name=TextEditingController(text:widget.product?['name']??''),price=TextEditingController(text:'${widget.product?['unit_price']??''}'),desc=TextEditingController(text:widget.product?['description']??''),min=TextEditingController(text:'${widget.product?['min_order_value']??0}');String? image;bool active=true,busy=false;@override void initState(){super.initState();image=widget.product?['image_url'];active=widget.product?['is_active']??true;}
Future<void> pick()async{final f=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:85);if(f==null)return;final path='${DateTime.now().millisecondsSinceEpoch}_${f.name}';try{await db.storage.from('product-images').upload(path,File(f.path));image=db.storage.from('product-images').getPublicUrl(path);setState((){});}catch(e){if(mounted)msg(context,'رفع الصورة فشل: $e');}}
Future<void> save()async{if(name.text.trim().isEmpty||double.tryParse(price.text)==null){msg(context,'اسم المنتج والسعر مطلوبان');return;}setState(()=>busy=true);try{final data={'name':name.text.trim(),'description':desc.text,'unit_price':double.parse(price.text),'min_order_value':double.tryParse(min.text)??0,'image_url':image,'is_active':active,'updated_at':DateTime.now().toUtc().toIso8601String()};if(widget.product==null)await db.from('products').insert(data);else await db.from('products').update(data).eq('id',widget.product!['id']);if(mounted)Navigator.pop(context);}catch(e){if(mounted)msg(context,'الحفظ فشل: $e');}finally{if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.product==null?'إضافة منتج':'تعديل منتج')),body:ListView(padding:const EdgeInsets.all(18),children:[GestureDetector(onTap:pick,child:Container(height:200,color:panel,child:image==null?const Icon(Icons.add_a_photo,size:50,color:blue):Image.network(image!,fit:BoxFit.contain))),const SizedBox(height:12),TextField(controller:name,decoration:const InputDecoration(labelText:'اسم المنتج')),const SizedBox(height:12),TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'السعر')),const SizedBox(height:12),TextField(controller:min,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الحد الأدنى')),const SizedBox(height:12),TextField(controller:desc,maxLines:4,decoration:const InputDecoration(labelText:'الوصف')),SwitchListTile(title:const Text('عرض المنتج للعملاء'),value:active,onChanged:(v)=>setState(()=>active=v)),const SizedBox(height:16),ElevatedButton(onPressed:busy?null:save,style:ElevatedButton.styleFrom(backgroundColor:blue),child:Text(busy?'جار الحفظ':'حفظ'))]));}
}
