class _OrdersState extends State<Orders>{Future<List<Map<String,dynamic>>> load()=>db.from('orders').select().order('created_at',descending:true);static const statuses=['pending','confirmed','processing','shipped','delivered','cancelled'];String label(String s)=>({'pending':'جديد','confirmed':'مؤكد','processing':'قيد التجهيز','shipped':'تم الشحن','delivered':'تم التسليم','cancelled':'ملغي'}[s]??s);
